<script setup lang="ts">
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import type {OfficialMenu} from '~/types/official-account'
const props=defineProps<{disabled:boolean}>(),menu=defineModel<OfficialMenu[]>({required:true}),parent=ref(0),child=ref<number|null>(null)
const selected=computed(()=>child.value===null?menu.value[parent.value]:menu.value[parent.value]?.children[child.value])
const fresh=():OfficialMenu=>({name:'新菜单',type:'view',url:'',appId:'',pagePath:'',children:[]})
function add(sub=false){if(props.disabled)return;if(sub){const row=menu.value[parent.value];if(!row||row.children.length>=5)return;row.type='group';row.url='';row.appId='';row.pagePath='';row.children.push(fresh());child.value=row.children.length-1}else{if(menu.value.length>=3)return;menu.value.push(fresh());parent.value=menu.value.length-1;child.value=null}}
function remove(){if(props.disabled)return;if(child.value===null){menu.value.splice(parent.value,1);parent.value=Math.max(0,parent.value-1)}else{const row=menu.value[parent.value];if(row){row.children.splice(child.value,1);if(!row.children.length)row.type='view'}child.value=null}}
function changeType(value:string){if(!selected.value||props.disabled)return;selected.value.type=value as OfficialMenu['type']}
</script>
<template><section class="surface-card official-content flex flex-col p-5 sm:p-7"><div class="grid flex-1 gap-7 lg:grid-cols-[20rem_1fr]">
 <div class="flex min-h-80 flex-col rounded-md border border-default"><p class="border-b border-default p-4 text-center text-sm text-muted">公众号菜单预览</p><div class="flex flex-1 items-end gap-2 p-3"><div v-for="(item,index) in menu" :key="index" class="min-w-0 flex-1 space-y-2"><div v-if="parent===index" class="space-y-1"><UButton v-for="(sub,n) in item.children" :key="n" type="button" class="w-full justify-center truncate" :color="child===n?'primary':'neutral'" variant="soft" @click="parent=index;child=n">{{sub.name}}</UButton><UButton v-if="item.children.length<5" type="button" class="w-full justify-center" color="neutral" variant="outline" icon="i-lucide-plus" :disabled="disabled" aria-label="添加子菜单" @click="add(true)"/></div><UButton type="button" class="w-full justify-center truncate" :color="parent===index&&child===null?'primary':'neutral'" variant="soft" @click="parent=index;child=null">{{item.name}}</UButton></div><UButton v-if="menu.length<3" type="button" class="min-w-10 justify-center" color="neutral" variant="outline" icon="i-lucide-plus" :disabled="disabled" aria-label="添加一级菜单" @click="add()"/></div></div>
 <div v-if="selected" class="space-y-6"><h2 class="text-sm font-semibold">菜单信息</h2><ConsoleSettingsField label="菜单名称" input-id="official-menu-name"><ConsoleInput id="official-menu-name" v-model="selected.name" required :maxlength="child===null?16:60" :disabled="disabled"/><p class="mt-2 text-xs text-muted">最多 3 个一级菜单，每个最多 5 个子菜单。名称按微信接口字节长度校验。</p></ConsoleSettingsField>
 <ConsoleSettingsField label="菜单类型" input-id="official-menu-type"><USelect id="official-menu-type" :model-value="selected.type" :items="selected.children?.length?[{label:'子菜单分组',value:'group'}]:[{label:'跳转网页',value:'view'},{label:'跳转小程序',value:'miniprogram'}]" :disabled="disabled" @update:model-value="changeType(String($event))"/></ConsoleSettingsField>
 <template v-if="selected.type!=='group'"><ConsoleSettingsField :label="selected.type==='miniprogram'?'备用网页链接':'网页链接'" input-id="official-menu-url"><ConsoleInput id="official-menu-url" v-model="selected.url" type="url" required :maxlength="1024" :disabled="disabled" placeholder="https://"/></ConsoleSettingsField><template v-if="selected.type==='miniprogram'"><ConsoleSettingsField label="小程序 AppID" input-id="official-menu-app"><ConsoleInput id="official-menu-app" v-model="selected.appId" required pattern="wx[a-fA-F0-9]{16}" :disabled="disabled"/></ConsoleSettingsField><ConsoleSettingsField label="页面路径" input-id="official-menu-path"><ConsoleInput id="official-menu-path" v-model="selected.pagePath" required :disabled="disabled" placeholder="pages/index/index"/></ConsoleSettingsField></template></template>
 <UButton type="button" color="error" variant="outline" icon="i-lucide-trash-2" :disabled="disabled" @click="remove">删除当前菜单</UButton></div><p v-else class="py-8 text-sm text-muted">点击“＋”添加一级菜单。</p>
 </div><p class="mt-6 border-t border-default pt-4 text-xs text-muted">先保存菜单草稿，再发布到微信。提交结果可在下方处理记录中查看。</p></section></template>
